#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
verify_motion.py —— 判断一个效果"到底有没有在动"

为什么需要它：只看平均亮度会漏掉"变亮但不动"的效果。
`Sunrise`(104) 就是这样：亮度 41→175 变化明显，但亮区恒在中点（源码里把同色镜像写到
`i` 与 `SEGLEN-1-i`），客户看到的是"太阳固定在一个区域"。平均亮度指标完全看不出来。

判据：**亮度加权质心**随时间的位置漂移。会走的效果，质心会扫过整条；
不动的效果，质心几乎不变（只有噪声级的抖动）。

用法：
    python3 scripts/verify_motion.py --ip 192.168.2.58 --seconds 12
    python3 scripts/verify_motion.py --ip 192.168.2.63 --seconds 12 --min-drift 0.5
    python3 scripts/verify_motion.py --ip <ip> --json

退出码：0 = 在动；1 = 没动 / 取不到帧。
"""
from __future__ import annotations

import argparse
import json
import sys
import time

import websocket


def frames(ip: str, seconds: float):
    ws = websocket.create_connection(f"ws://{ip}/ws", timeout=5)
    ws.send('{"lv":true}')
    ws.settimeout(0.05)
    out, t0, prev = [], time.time(), None
    while time.time() - t0 < seconds:
        try:
            d = ws.recv()
        except Exception:
            continue
        if isinstance(d, (bytes, bytearray)) and len(d) > 5 and d[0] == ord("L") and d[1] == 1:
            f = bytes(d[2:])
            n = len(f) // 3
            if n < 2:
                continue
            luma = [(f[i * 3] + f[i * 3 + 1] + f[i * 3 + 2]) / 3.0 for i in range(n)]
            total = sum(luma) or 1.0
            centroid = sum(i * v for i, v in enumerate(luma)) / total / (n - 1)
            # 变化量质心：静态亮底会把"亮度质心"摊平，但有东西在走时
            # |本帧-上帧| 的分布会跟着那个东西移动 —— 这才是"有没有在走"的仪器。
            if prev is not None:
                d = [abs(luma[i] - prev[i]) for i in range(n)]
                dsum = sum(d) or 1.0
                dcent = sum(i * v for i, v in enumerate(d)) / dsum / (n - 1)
            else:
                dcent = 0.0
            prev = luma
            out.append((round(time.time() - t0, 2), centroid, sum(luma) / n, n, dcent))
    try:
        ws.send('{"lv":false}')
        ws.close()
    except Exception:
        pass
    return out


def main() -> int:
    ap = argparse.ArgumentParser(description="判断效果是否真的在动（亮度质心位移）")
    ap.add_argument("--ip", required=True)
    ap.add_argument("--seconds", type=float, default=12.0, help="采样时长（默认 12s，够看一个来回）")
    ap.add_argument("--min-drift", type=float, default=0.35,
                    help="质心相对位移达到多少才算'在动'（0..1，默认 0.35）")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args()

    f = frames(args.ip, args.seconds)
    if not f:
        print("取不到帧：检查 IP / 是否已被别的客户端占用 WebSocket", file=sys.stderr)
        return 1

    cs = [c for _, c, _, _, _ in f]
    dcs = [d for _, _, _, _, d in f]
    drift = max(cs) - min(cs)
    ddrift = max(dcs) - min(dcs)
    # 累计绝对位移 / 1.0 ≈ 扫过多少条（用来估"几圈"）
    swept = sum(abs(cs[i] - cs[i - 1]) for i in range(1, len(cs)))
    moving = drift >= args.min_drift or ddrift >= args.min_drift

    if args.json:
        print(json.dumps({
            "ip": args.ip, "frames": len(f), "leds": f[0][3],
            "drift": round(drift, 3), "change_drift": round(ddrift, 3), "swept": round(swept, 2),
            "centroid_path": [round(c, 2) for c in cs[:: max(1, len(cs) // 8)]],
            "mean_luma_at_start": round(f[0][2], 1), "mean_luma_at_end": round(f[-1][2], 1),
            "moving": moving, "min_drift": args.min_drift,
        }, ensure_ascii=False, indent=2))
        return 0 if moving else 1

    step = max(1, len(f) // 8)
    path = " → ".join(f"{c:.2f}" for c in cs[::step])
    print(f"{args.ip}  {f[0][3]} 颗  {len(f)} 帧 / {args.seconds:g}s")
    print(f"  质心轨迹 {path}")
    step2 = max(1, len(f) // 8)
    dpath = " → ".join(f"{d:.2f}" for d in dcs[::step2])
    print(f"  变化质心 {dpath}")
    print(f"  亮度质心位移 {drift:.2f}   变化质心位移 {ddrift:.2f}（阈值 {args.min_drift}）  累计扫过 {swept:.2f} 条")
    print(f"  亮度 {f[0][2]:.0f} → {f[-1][2]:.0f}")
    print("  判定：" + ("在动" if moving else "没动（亮度与变化量都没有位移）"))
    return 0 if moving else 1


if __name__ == "__main__":
    sys.exit(main())
# AI: end
